209: // ── LLM availability check (3s timeout, uses chat/completions) ──────
210: async function checkLLMAvailability(url: string, key: string): Promise<boolean> {
211:   if (key === 'sk-placeholder') return false;
212:   try {
213:     const controller = new AbortController();
214:     const timeout = setTimeout(() => controller.abort(), 10_000);
215:     const res = await fetch(`${url}/chat/completions`, {
216:       method: 'POST',
217:       headers: {
218:         'Authorization': `Bearer ${key}`,
219:         'Content-Type': 'application/json',
220:       },
221:       body: JSON.stringify({
222:         model: model,
223:         messages: [{ role: 'user', content: 'ping' }],
224:         max_tokens: 1,
225:       }),
226:       signal: controller.signal,
227:     });
228:     clearTimeout(timeout);
229:     if (res.ok) return true;
230:     // 401/403 = invalid key → unavailable
231:     if (res.status === 401 || res.status === 403) return false;
232:     // 4xx (except 429 rate limit) = misconfigured endpoint → unavailable
233:     if (res.status >= 400 && res.status < 500 && res.status !== 429) return false;
234:     // 5xx or other = might be transient, treat as available
235:     return true;
236:   } catch {
237:     return false;
238:   }
239: }
