324: /** Render an altitude bar chart showing per-line stage progression */
325: function renderAltitudesChart(sig: Significator): void {
326:   const orderedLines: Line[] = ['Cognitive', 'Emotional', 'Moral', 'Intrapersonal', 'Spiritual', 'Somatic', 'Willpower', 'Interpersonal'];
327:   const allStages = ['Infrared', 'Magenta', 'Red', 'Amber', 'Orange', 'Green', 'Turquoise', 'White'] as const;
328:   const stageKeys: readonly string[] = allStages;
329: 
330:   for (const line of orderedLines) {
331:     const current = sig.altitudes[line] ?? 'Red';
332:     const currentIdx = stageKeys.indexOf(current);
333:     const color = stageColor(current);
334: 
335:     // Build a horizontal bar: filled squares up to current stage, empty beyond
336:     const bars = stageKeys.map((s, i) => {
337:       if (i < currentIdx) return chalk.dim('■');  // passed stages
338:       if (i === currentIdx) return color('●'); // current stage
339:       return chalk.dim('○'); // future stages
340:     });
341: 
342:     // Segment label: first 3 stages, current, last 2
343:     const segLabels = stageKeys.map((s, i) => {
344:       if (i === 0 || i === stageKeys.length - 1 || i === currentIdx) {
345:         return i === currentIdx ? color(stageAbbr(s)) : chalk.dim(stageAbbr(s));
346:       }
347:       return '  '; // skip most labels for compactness
348:     });
349: 
350:     // Pad line name to 15 chars for alignment
351:     const paddedLine = line.padEnd(14);
352:     if (!JSON_MODE) {
353:       console.log(`  ${paddedLine} ${bars.join('')} ${chalk.dim(current)}`);
354:     }
