382: /** Render session arc position with progress bar */
383: function renderSessionPosition(label: string, position: 'warmup' | 'peak' | 'cooldown', progress: number): void {
384:   if (JSON_MODE) return;
385:   const barLen = 12;
386:   const pos = Math.round(progress * barLen);
387:   let bar = '';
388:   for (let i = 0; i < barLen; i++) {
389:     if (position === 'warmup') {
390:       bar += i <= pos ? chalk.blue('▰') : chalk.dim('▱');
391:     } else if (position === 'peak') {
392:       bar += i <= pos ? chalk.magenta('▰') : chalk.dim('▱');
393:     } else {
394:       bar += i <= pos ? chalk.green('▰') : chalk.dim('▱');
395:     }
396:   }
397:   const posLabel = position === 'warmup' ? chalk.blue('WARMUP')
398:     : position === 'peak' ? chalk.magenta('PEAK')
399:     : chalk.green('COOLDOWN');
400:   console.log(`  ${posLabel} ${bar} ${chalk.dim(label)}`);
