446:     const w = sig.drives.weights[d] ?? 0;
447:     const fix = sig.drives.fixationRisk[d] ?? 0;
448:     const filled = Math.max(0, Math.round((w / maxVal) * barLen));
449:     const bar = '█'.repeat(filled) + '░'.repeat(barLen - filled);
450:     const color = fix > 0.5 ? chalk.red : w > 0.3 ? chalk.green : chalk.yellow;
451:     const fixIcon = fix > 0.7 ? '⚠' : fix > 0.4 ? '~' : ' ';
452:     const dirIcon = w > 0.6 ? '↑' : w < 0.35 ? '↓' : ' ';
453:     console.log(`  ${chalk.dim(d.padEnd(10))} ${color(bar)} ${fixIcon}${dirIcon} ${chalk.dim(fix > 0.1 ? `fix:${(fix * 100).toFixed(0)}%` : '')}`);
