484:   responsesPool?: number[],
485:   consecutivePasses?: Map<string, number>,
486: ): Promise<{
487:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
488:   response: PlayerResponse;
489:   narrativeSummary: string;
490: }> {
491:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
492:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
493: 
494:   // If --line/--stage/--modality forcing is active, override the encounter
495:   let forcedEncounter = encounter;
496:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
497:     const forcedLine = FORCE_LINE ?? encLine;
498:     const forcedStage = FORCE_STAGE ?? encStage;
499:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
500:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
501:     if (forcedModule) {
502:       forcedEncounter = {
503:         ...encounter,
504:         moduleRef: `${forcedLine}:${forcedStage}`,
505:         modality: forcedModality,
506:         targetLines: [forcedLine],
507:         stage: forcedStage,
508:       };
509:     }
510:   }
511: 
512:   const uiHandler: AgenticUIHandler = {
513:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
514:       const answers: UserAnswer[] = [];
515: 
516:       for (const q of params.questions) {
517:         if (!JSON_MODE) {
518:           const mod = forcedEncounter.modality;
519:           let modHeader = '';
520: 
521:           switch (mod) {
522:             case 'Deterministic':
523:               modHeader = `${chalk.bold.red('⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`;
524:               break;
525:             case 'LanguageReflective':
526:               modHeader = `${chalk.bold.blue('🧘 [REFLECTION BEAT] • Tune in to your inner state •')}\n`;
527:               break;
528:             case 'ScenarioChoice':
529:               modHeader = `${chalk.bold.yellow('🔀 [DECISION CROSSROADS] • A path diverges •')}\n`;
530:               break;
531:             case 'Embodied':
532:               modHeader = `${chalk.bold.green('💓 [SOMATIC SCAN] • Focus on body sensation •')}\n`;
533:               break;
534:             case 'Strategic':
535:               modHeader = `${chalk.bold.magenta('♟️ [TACTICAL WAR-TABLE] • Assess constraints •')}\n`;
536:               break;
537:             case 'SocialCooperative':
538:               modHeader = `${chalk.bold.cyan('🤝 [DIPLOMACY] • Navigating connection •')}\n`;
539:               break;
540:             case 'ImmersiveRPG':
541:               modHeader = `${chalk.bold.yellow('📖 [NARRATIVE SCENE] • The story unfolds •')}\n`;
542:               break;
543:             default:
544:               modHeader = `${chalk.bold.dim('[' + (mod as string).toUpperCase() + ']')}\n`;
545:           }
546: 
547:           console.log(`\n  ${modHeader}  ${chalk.magenta('[' + q.header + ']')}`);
548:           console.log(`  ${chalk.bold(q.question)}`);
549:           if (q.options?.length) {
550:             for (let i = 0; i < q.options.length; i++) {
551:               const opt = q.options[i];
552:               console.log(`    ${chalk.cyan('[' + (i + 1) + ']')} ${opt.label} — ${opt.description}`);
553:             }
554:           }
555:         }
556: 
557:         emitEvent('ask_user', {
558:           header: q.header,
559:           question: q.question,
560:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
561:           allowWriteIn: q.allowWriteIn,
562:         });
563: 
564:         if (HEADLESS) {
565:           // Use forced responses pool if provided (one index per question, consumed sequentially)
566:           let selectedIdx: number;
567:           if (responsesPool && responsesPool.length > 0) {
568:             const forcedIdx = responsesPool.shift()!;
569:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
570:               selectedIdx = forcedIdx - 1;
571:             } else {
572:               selectedIdx = 0;
573:             }
574:           } else {
575:             // Vary selection to probe different shadow patterns:
576:             // Cycle through options to ensure shadow detection has varied input
577:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
578:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
579:           }
580:           const selectedOpt = q.options?.[selectedIdx];
581:           const selectedLabel = selectedOpt?.label ?? '';
582: 
583:           // Shadow keyword injection for testing — randomly inject (10% chance)
584:           // to allow MOST encounters to pass and demonstrate altitude shifts.
585:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
586:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
587:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
588:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
589: 
590:           if (writeInShadow) {
591:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
592:           } else {
593:             answers.push({ selectedLabels: [selectedLabel] });
594:           }
595:         } else {
596:           const promptText = q.multiSelect
597:             ? '\n  Select (comma-separated): '
598:             : '\n  Select: ';
599:           const answer = await ask(promptText);
600:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
601:           const selectedLabels = selections
602:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
603:             .map(n => q.options![n - 1]!.label);
604: 
605:           // Determine if input is a simple numeric choice from the options
606:           let isSimpleNumericChoice = false;
607:           if (q.options?.length && answer.trim()) {
608:             const parts = answer.split(',').map(s => s.trim());
609:             isSimpleNumericChoice = parts.every(part => {
610:               const num = parseInt(part, 10);
611:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
612:             });
613:           }
614: 
615:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
616:             // Only populate writeInValue if it's NOT a simple numeric choice
617:             if (!isSimpleNumericChoice && answer.trim()) {
618:               answers.push({ selectedLabels, writeInValue: answer.trim() });
619:             } else {
620:               answers.push({ selectedLabels });
621:             }
622:           } else {
623:             answers.push({ selectedLabels });
624:           }
625:         }
626:       }
627: 
628:       return { answers };
629:     }
630:   };
631: 
632:   // Always route through AgenticOrchestrator — it handles LLM + fallback internally
633:   // Look up the assessment module from the registry to inject into the LLM context
634:   const baseModule = modRegistry?.get(encLine, encStage);
635: 
636:   // Build ConceptDraftIndex from the module registry so the LLM sees module metadata
637:   const conceptModules: Record<string, any> = {};
638:   if (modRegistry) {
639:     for (const m of modRegistry.getAll()) {
640:       const key = `${m.line.toLowerCase()}:${m.stage.toLowerCase()}`;
641:       conceptModules[key] = {
642:         line: m.line,
643:         stage: m.stage,
644:         title: `${m.line} ${m.stage} Module`,
645:         modalities: m.tasks.map(t => t.type === 'llm_dialogue' ? 'LanguageReflective' as const : 'Deterministic' as const),
646:       };
647:     }
648:   }
649: 
650:   const orchestrator = new AgenticOrchestrator({
651:     encounter: forcedEncounter,
652:     significator: sig,
653:     world,
654:     history,
655:     conceptIndex: { modules: conceptModules },
656:     uiHandler,
657:     module: modRegistry?.get(FORCE_LINE ?? encLine, FORCE_STAGE ?? encStage) ?? baseModule,
658:     noLlm: !LLM_ACTIVE,
659:     forceShadow: FORCE_SHADOW,
660:     consecutivePasses,
661:   });
662: 
663:   const outcome = await orchestrator.run();
664: 
665:   // Build a PlayerResponse from the orchestrator's consequence record
666:   const cr = outcome.consequenceRecord;
667:   const response: PlayerResponse = {
668:     encounterId: encounter.id,
669:     energeticDirection: cr.polarityTrace.energeticDirection,
670:     driveDirectionality: cr.polarityTrace.driveDirectionality,
671:     stageOrientation: cr.polarityTrace.stageOrientation,
672:     sourceOfNourishment: cr.polarityTrace.sourceOfNourishment,
673:     shadowSurfaced: cr.shadowSurfaced,
674:     shadowResolvedId: cr.shadowResolved,
675:     narrativeSummary: outcome.narrativeSummary,
676:   };
677: 
678:   return { outcome, response, narrativeSummary: outcome.narrativeSummary };
679: }
