  'Infrared',
  'Magenta',
  'Red',
  'Amber',
  'Orange',
  'Green',
  'Turquoise',
  'White',
];

/** Ordinal index of a stage (0 = Infrared, 7 = White). */
export function stageOrdinal(s: Stage): number {
  return ALL_STAGES.indexOf(s);
}

